/bin/zsh -lc "apply_patch <<'PATCH'
*** Begin Patch
*** Delete File: TopModule.sv
*** Add File: TopModule.sv
+module TopModule(
+    input       [3:0]       A_in  ,
+    input       [3:0]       B_in  ,
+    input                   C_1   ,
+  
+    output   wire           CO    ,
+    output   wire [3:0]     S
+);
+    wire [3:0] G, P, C;
+    wire c0_and, c1_and, c2_and, c3_and;
+
+    xor (P, A_in, B_in);
+    and (G, A_in, B_in);
+
+    and (c0_and, P[0], C_1);
+    or  (C[0], G[0], c0_and);
+
+    and (c1_and, P[1], C[0]);
+    or  (C[1], G[1], c1_and);
+
+    and (c2_and, P[2], C[1]);
+    or  (C[2], G[2], c2_and);
+
+    and (c3_and, P[3], C[2]);
+    or  (C[3], G[3], c3_and);
+
+    xor (S[0], P[0], C_1);
+    xor (S[1], P[1], C[0]);
+    xor (S[2], P[2], C[1]);
+    xor (S[3], P[3], C[2]);
+
+    buf (CO, C[3]);
+    
+endmodule
*** End Patch
PATCH

cat > tb.sv <<'TB'
module tb;
  reg [3:0] A_in;
  reg [3:0] B_in;
  reg C_1;
  wire CO;
  wire [3:0] S;

  TopModule dut (
    .A_in(A_in),
    .B_in(B_in),
    .C_1(C_1),
    .CO(CO),
    .S(S)
  );

  integer a, b, c;
  reg [4:0] expected;
  initial begin
    for (a = 0; a < 16; a = a + 1) begin
      for (b = 0; b < 16; b = b + 1) begin
        for (c = 0; c < 2; c = c + 1) begin
          A_in = a[3:0];
          B_in = b[3:0];
          C_1 = c[0];
          #1;
          expected = a + b + c;
          if ({CO, S} "'!== expected) begin
            $display("Mismatch: A=%0h B=%0h Cin=%0h got=%0h expected=%0h", A_in, B_in, C_1, {CO, S}, expected);
            $finish(1);
          end
        end
      end
    end
    $display("PASS");
    $finish;
  end
endmodule
TB

iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

